def _collage():
    cats=[k for k,_ in CATS]; out=[]; seen=set()
    for i in range(60):
        for p in PRODUCTS:
            if p["c"]==cats[i%5] and p.get("m") and p["b"] not in seen: out.append(p); seen.add(p["b"]); break
        if len(out)==6: break
    return out
