doc("cookies","Cookie Policy","How pivoxmarket.com uses cookies and similar technologies.",f"""<p>This policy explains how {NAME} ("Pivox," "we," "us") uses cookies and similar technologies on {DOMAIN}.</p><h2>What are cookies?</h2><p>Cookies are small text files that websites store on your device. They can keep a site working, remember preferences, or measure and advertise.</p><h2>What we use</h2><p>Our site does not currently set advertising or analytics cookies, and we do not use tracking pixels to follow you across other sites. If we add analytics or advertising tools in the future, we will update this policy and, where required, ask for your consent first.</p><h2>Third-party services</h2><ul><li><strong>Fonts:</strong> our pages load fonts from Google Fonts, so your browser sends a request to Google that includes your IP address.</li><li><strong>Hosting:</strong> our hosting provider keeps standard server logs (such as IP address, browser type and pages requested) for security and reliability.</li></ul><h2>Your choices</h2><p>You can block or delete cookies in your browser settings. Browsers also let you send a "Do Not Track" or Global Privacy Control signal. Because we do not sell your information or use it for targeted advertising, these signals do not change how we handle it.</p><h2>More information</h2><p>See our <a href="/privacy.html">Privacy Policy</a> or contact us:</p><p>{NAME}<br>{contact_lines}</p>""")
doc("privacy-choices","Your Privacy Choices","Privacy rights for residents of California and other U.S. states, and how to exercise them with Pivox LLC.",f"""<p>Residents of California and other U.S. states with privacy laws have certain rights over their personal information. This page explains those rights and how to use them. It supplements our <a href="/privacy.html">Privacy Policy</a>.</p><h2>We do not sell or share your information</h2><p>{NAME} does not sell your personal information, and we do not share it for cross-context behavioral (targeted) advertising. We do not knowingly sell or share the personal information of anyone under 16.</p><h2>Information we collect</h2><p>In the past 12 months we may have collected: identifiers (name, address, email, phone number); commercial information (orders and inquiries); and limited internet activity (server logs). We use it to answer inquiries, process and deliver orders, prevent fraud and meet legal duties, and disclose it only to service providers such as payment processors, carriers and warehouses. We do not collect sensitive personal information for purposes other than providing the products you request.</p><h2>Your rights</h2><ul><li><strong>Know and access:</strong> ask what personal information we hold about you and receive a copy.</li><li><strong>Delete:</strong> ask us to delete your personal information, subject to legal exceptions.</li><li><strong>Correct:</strong> ask us to fix inaccurate information.</li><li><strong>Opt out:</strong> of sale, sharing and targeted advertising (we do none of these).</li><li><strong>No retaliation:</strong> we will not treat you differently for using your rights.</li></ul><h2>How to make a request</h2><p>Contact us {reach}by mail at the address below, and include your name, the email or address used for your order, and the request you are making. We will verify your identity before acting, and respond within 45 days (we will tell you if we need more time). You may use an authorized agent; we may ask for proof of their authority.</p><h2>Appeals</h2><p>If we decline your request and your state gives you the right to appeal, reply with the word "Appeal" and your reasons, and we will review it and respond in writing.</p><h2>California "Shine the Light"</h2><p>We do not disclose personal information to third parties for their own direct marketing purposes.</p><h2>Contact</h2><p>{NAME}<br>{contact_lines}</p>""")
doc("product-information","Product Information and Recalls","Product labels, allergens, dating and recall information for products sold by Pivox Market.",f"""<h2>Always read the label</h2><p>Product names, sizes and images on this site are provided for identification. Manufacturers change recipes, ingredients, packaging and sizes from time to time, so the label on the package you receive is the most accurate source for ingredients, allergens, nutrition facts and directions.</p><h2>Allergens</h2><p>Many foods contain or are made near major allergens such as milk, eggs, fish, shellfish, tree nuts, peanuts, wheat, soy and sesame. If you have an allergy or dietary restriction, check the full label before eating, and contact the manufacturer with questions. We repackage nothing, so allergen warnings are those of the original manufacturer.</p><h2>Dating and storage</h2><p>We aim to ship products with reasonable remaining shelf life. If an item arrives past its best-by or use-by date, contact us and we will replace it or refund it under our <a href="/returns.html">Return Policy</a>. Store products as directed on the label.</p><h2>Recalls</h2><p>If a manufacturer or a government agency recalls a product we sold, we will contact affected customers by email where we can and offer a refund. You can also check current recalls at <a href="https://www.fda.gov/safety/recalls-market-withdrawals-safety-alerts">fda.gov</a>. If you have a product you believe is unsafe, stop using it and contact us right away.</p><h2>Not medical advice</h2><p>Information on this site is not medical or nutritional advice. Talk to a healthcare professional about dietary needs.</p><h2>Contact</h2><p>{NAME}<br>{contact_lines}</p>""")

# ---- one page per product + sitemap ----
import os, shutil, json as _json
from html import escape as _h
shutil.rmtree("product", ignore_errors=True); os.makedirs("product")
_brand, _cat, CATN = {}, {}, dict(CATS)
for _p in PRODUCTS: _brand.setdefault(_p["b"], []).append(_p); _cat.setdefault(_p["c"], []).append(_p)
def related(p):
    L = _brand[p["b"]]; i = L.index(p); r = (L[i+1:] + L[:i])[:4]
    if len(r) < 4:
        pool = [q for q in _cat[p["c"]] if q["b"] != p["b"]]
        if pool: s = int(p["u"]) % len(pool); r += (pool[s:] + pool[:s])[:4-len(r)]
    return r
def pdp(p):
    u, b, n, s, c = p["u"], p["b"], p["n"], p["s"], p["c"]
    bq = quote(b); mail = f"mailto:{EMAIL}?subject=" + quote(f"Inquiry: {b} {n} ({u})")
    if p.get("m"): pic = f"<div class='pdp-img'><img src='/images/products/{p['m']}' alt='{_h(b+' '+n+', '+s)}'></div>"
    else: pic = f"<div class='pdp-img ill' style='--c:{COL[c]}'><svg viewBox='0 0 240 240' aria-hidden='true'><use href='/sprites.svg#{SHAPES[p['h']]}-{p['k']}'/></svg></div>"
    url = f"https://{DOMAIN}/product/{u}.html"
    ld = {"@context":"https://schema.org","@type":"Product","name":f"{b} {n}","brand":{"@type":"Brand","name":b},"sku":u.zfill(12),"gtin12":u.zfill(12),"category":CATN[c],
          "offers":{"@type":"Offer","url":url,"price":f"{p['p']:.2f}","priceCurrency":"USD","seller":{"@type":"Organization","name":NAME}}}
    if p.get("m"): ld["image"] = f"https://{DOMAIN}/images/products/{p['m']}"
    ldj = _json.dumps(ld, ensure_ascii=False).replace("</", "<\\/")
    bcj = _json.dumps({"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":i+1,"name":nm,"item":it} for i,(nm,it) in enumerate([("Shop",f"https://{DOMAIN}/products.html"),(CATN[c],f"https://{DOMAIN}/category/{c}.html"),(b,f"https://{DOMAIN}/brand/{slug(b)}.html"),(n,url)])]}, ensure_ascii=False).replace("</","<\\/")
    rel = "".join(card(q, EMAIL) for q in related(p))
    body = f"""<section class="wrap pdp-wrap"><nav class="crumbs" aria-label="Breadcrumb"><a href="/products.html">Shop</a> / <a href="/category/{c}.html">{CATN[c]}</a> / <a href="/brand/{slug(b)}.html">{_h(b)}</a></nav>
<div class="pdp">{pic}<div class="pdp-info"><p class="brand"><a href="/brand/{slug(b)}.html">{_h(b)}</a></p><h1>{_h(n)}</h1><p class="size">{_h(s)}</p><p class="pdp-price">${p['p']:.2f}</p><a class="pill dark" href="{mail}">Ask about availability</a>
<p class="small" style="margin-top:14px">To order, email <a href="mailto:{EMAIL}">{EMAIL}</a>. Ships from U.S. warehouses. See our <a href="/shipping.html">shipping</a> and <a href="/returns.html">return</a> policies.</p>
<dl class="facts"><div><dt>Brand</dt><dd>{_h(b)}</dd></div><div><dt>Size</dt><dd>{_h(s)}</dd></div><div><dt>Category</dt><dd>{CATN[c]}</dd></div><div><dt>UPC</dt><dd>{u.zfill(12)}</dd></div></dl></div></div>
<h2>More like this</h2><div class="cards">{rel}</div></section><script type="application/ld+json">{ldj}</script><script type="application/ld+json">{bcj}</script>"""
    page(f"product/{u}", f"{n} by {b}", f"{b} {n}, {s}. ${p['p']:.2f}. Shipped from U.S. warehouses by Pivox Market.", body, og_type="product", img=(f"https://{DOMAIN}/images/products/{p['m']}" if p.get("m") else None))
for _p in PRODUCTS: pdp(_p)
shutil.rmtree("brand", ignore_errors=True); shutil.rmtree("category", ignore_errors=True); os.makedirs("brand"); os.makedirs("category")
def listing(kind, key, title, desc, crumb, h1, lead, prods, shop_href):
    cards = "".join(card(p, EMAIL) for p in prods[:60])
    more = f"<p class='more-wrap'><a class='pill dark' href='{shop_href}'>Search all {len(prods)} products in the shop</a></p>" if len(prods) > 60 else ""
    page(f"{kind}/{key}", title, desc, f"<section class='wrap doc wide'><nav class='crumbs' aria-label='Breadcrumb'><a href='/products.html'>Shop</a> / {crumb}</nav><h1>{h1}</h1><p class='lead'>{lead}</p><div class='cards'>{cards}</div>{more}</section>")
for _k, _l in CATS:
    _ps = _cat.get(_k, [])
    if _ps: listing("category", _k, _l, f"Shop {_l.lower()} at Pivox Market: {len(_ps)} products from {len({x['b'] for x in _ps})} brands, shipped from U.S. warehouses.", _h(_l), _h(_l), f"{len(_ps)} products from {len({x['b'] for x in _ps})} brands.", _ps, f"/products.html?cat={_k}")
for _b, _ps in _brand.items():
    _top = ", ".join(x["n"] for x in _ps[:3])
    listing("brand", slug(_b), f"{_b} Products", f"Shop {len(_ps)} {_b} products at Pivox Market, including {_top}. Shipped from U.S. warehouses.", f"<a href='/brands.html'>Brands</a> / {_h(_b)}", _h(_b), f"{len(_ps)} {_h(_b)} products available.", _ps, f"/products.html?brand={quote(_b)}")
_urls = [""] + [f"{x}.html" for x in ("products","brands","about","contact","shipping","returns","privacy","terms","accessibility","cookies","privacy-choices","product-information")] + [f"product/{p['u']}.html" for p in PRODUCTS] + [f"category/{k}.html" for k,_ in CATS if k in _cat] + [f"brand/{slug(x)}.html" for x in _brand]
open("sitemap.xml","w").write('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + "".join(f"<url><loc>https://{DOMAIN}/{x}</loc><lastmod>{__import__('datetime').date.today().isoformat()}</lastmod></url>" for x in _urls) + "</urlset>")
open("robots.txt","w").write(f"User-agent: *\nAllow: /\nSitemap: https://{DOMAIN}/sitemap.xml\n")
print(len(PRODUCTS), "product pages written")
